50	// Budget figures are shown with thousands separators (e.g. $1,000.00) so larger amounts stay
51	// readable at a glance.
52	function moneyGrouped(amount: number): string {
53	  return `$${Number(amount).toLocaleString('en-US', {
54	    minimumFractionDigits: 2,
55	    maximumFractionDigits: 2,
56	  })}`;
57	}
