65	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
66	// many, price each), the total worked out for you, and a form to add another line. Each line can be
67	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
68	// own line-item state, scoped to the one invoice it is showing.
69	function InvoiceDetail({
70	  invoiceId,
71	  onChange,
72	  onClose,
73	}: {
74	  invoiceId: number;
75	  onChange: () => void;
76	  onClose: () => void;
77	}) {
78	  const [items, setItems] = useState<EditItem[]>([]);
79	  const [description, setDescription] = useState('');
80	  const [qty, setQty] = useState('');
81	  const [unit, setUnit] = useState('');
82	  const [unitPrice, setUnitPrice] = useState('');
83	  const [payments, setPayments] = useState<Payment[]>([]);
84	  const [paymentAmount, setPaymentAmount] = useState('');
85	  const [paymentDate, setPaymentDate] = useState('');
86	  const [status, setStatus] = useState('');
87	
88	  // The status is worked out from the payments recorded against the invoice, so re-read it whenever
89	  // a payment is added rather than flipping it by hand.
90	  async function loadStatus() {
91	    const res = await fetch(`/api/invoices/${invoiceId}`);
92	    const inv: Invoice = await res.json();
93	    setStatus(inv.status);
94	  }
95	
96	  async function load() {
97	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
98	    const rows: LineItem[] = await res.json();
99	    setItems(
100	      rows.map((li) => ({
101	        id: li.id,
102	        description: li.description,
103	        qty: String(li.qty),
104	        unit: li.unit,
105	        unitPrice: String(li.unitPrice),
106	      })),
107	    );
108	  }
109	
110	  async function loadPayments() {
111	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
112	    setPayments(await res.json());
113	  }
114	
115	  async function submitPayment(e: React.FormEvent) {
116	    e.preventDefault();
117	    const value = Number(paymentAmount);
118	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
119	      return;
120	    }
121	    if (paymentDate.trim() === '') {
122	      return;
123	    }
124	    await fetch(`/api/invoices/${invoiceId}/payments`, {
125	      method: 'POST',
126	      headers: { 'Content-Type': 'application/json' },
127	      body: JSON.stringify({ amount: value, date: paymentDate }),
128	    });
129	    setPaymentAmount('');
130	    setPaymentDate('');
131	    await loadPayments();
132	    await loadStatus();
133	    onChange();
134	  }
135	
136	  useEffect(() => {
137	    void load();
138	    void loadPayments();
139	    void loadStatus();
140	  }, [invoiceId]);
141	
142	  function editField(
143	    id: number,
144	    field: 'description' | 'qty' | 'unit' | 'unitPrice',
145	    value: string,
146	  ) {
147	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
148	  }
149	
150	  function amountOf(li: EditItem): number {
151	    const line = Number(li.qty) * Number(li.unitPrice);
152	    return Number.isFinite(line) ? line : 0;
153	  }
154	
155	  async function save(li: EditItem) {
156	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
157	      return;
158	    }
159	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
160	      method: 'POST',
161	      headers: { 'Content-Type': 'application/json' },
162	      body: JSON.stringify({
163	        description: li.description,
164	        qty: Number(li.qty),
165	        unit: li.unit,
166	        unitPrice: Number(li.unitPrice),
167	      }),
168	    });
169	    await load();
170	    onChange();
171	  }
172	
173	  async function remove(id: number) {
174	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
175	    await load();
176	    onChange();
177	  }
178	
179	  async function submit(e: React.FormEvent) {
180	    e.preventDefault();
181	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
182	      return;
183	    }
184	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
185	      method: 'POST',
186	      headers: { 'Content-Type': 'application/json' },
187	      body: JSON.stringify({
188	        description,
189	        qty: Number(qty),
190	        unit,
191	        unitPrice: Number(unitPrice),
192	      }),
193	    });
194	    setDescription('');
195	    setQty('');
196	    setUnit('');
197	    setUnitPrice('');
198	    await load();
199	    onChange();
200	  }
201	
202	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
203	
204	  return (
205	    <section data-testid="invoice-detail">
206	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
207	        Back to invoices
208	      </button>
209	
210	      <p data-testid="invoice-status">{status}</p>
211	
212	      <table data-testid="invoice-lineitems-table">
213	        <tbody>
214	          {items.map((li) => (
215	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
216	              <td>
217	                <input
218	                  data-testid="lineitem-description"
219	                  value={li.description}
220	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
221	                />
222	              </td>
223	              <td data-testid="lineitem-qty">{li.qty}</td>
224	              <td data-testid="lineitem-unit">{li.unit}</td>
225	              <td>
226	                <input
227	                  data-testid="lineitem-unitprice"
228	                  value={li.unitPrice}
229	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
230	                />
231	              </td>
232	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
233	              <td>
234	                <button
235	                  data-testid={`lineitem-save-${li.id}`}
236	                  type="button"
237	                  onClick={() => save(li)}
238	                >
239	                  Save
240	                </button>
241	                <button
242	                  data-testid={`lineitem-remove-${li.id}`}
243	                  type="button"
244	                  onClick={() => remove(li.id)}
245	                >
246	                  Remove
247	                </button>
248	              </td>
249	            </tr>
250	          ))}
251	        </tbody>
252	      </table>
253	
254	      <p data-testid="invoice-amount">{money(total)}</p>
255	
256	      <form data-testid="lineitem-form" onSubmit={submit}>
257	        <input
258	          data-testid="lineitem-form-description"
259	          placeholder="Description"
260	          value={description}
261	          onChange={(e) => setDescription(e.target.value)}
262	        />
263	        <input
264	          data-testid="lineitem-form-qty"
265	          placeholder="How many"
266	          value={qty}
267	          onChange={(e) => setQty(e.target.value)}
268	        />
269	        <input
270	          data-testid="lineitem-form-unit"
271	          placeholder="Unit"
272	          value={unit}
273	          onChange={(e) => setUnit(e.target.value)}
274	        />
275	        <input
276	          data-testid="lineitem-form-unitprice"
277	          placeholder="Price each"
278	          value={unitPrice}
279	          onChange={(e) => setUnitPrice(e.target.value)}
280	        />
281	        <button data-testid="lineitem-form-submit" type="submit">
282	          Add line item
283	        </button>
284	      </form>
285	
286	      <table data-testid="invoice-payments-table">
287	        <tbody>
288	          {payments.map((p) => (
289	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
290	              <td data-testid="payment-amount">{money(p.amount)}</td>
291	              <td data-testid="payment-date">{p.date}</td>
292	            </tr>
293	          ))}
294	        </tbody>
295	      </table>
296	
297	      <form data-testid="payment-form" onSubmit={submitPayment}>
298	        <input
299	          data-testid="payment-form-amount"
300	          placeholder="Amount paid"
301	          value={paymentAmount}
302	          onChange={(e) => setPaymentAmount(e.target.value)}
303	        />
304	        <input
305	          data-testid="payment-form-date"
306	          type="date"
307	          value={paymentDate}
308	          onChange={(e) => setPaymentDate(e.target.value)}
309	        />
310	        <button data-testid="payment-form-submit" type="submit">
311	          Record payment
312	        </button>
313	      </form>
314	    </section>
315	  );
