318	// Which lifecycle actions an invoice offers depends on where it is in its lifecycle: a draft can be
319	// sent, a sent invoice can be marked paid. Collecting the mapping here keeps the row markup flat and
320	// gives one obvious place to add a new lifecycle action.
321	function InvoiceActions({
322	  invoice,
323	  onOpen,
324	  onSend,
325	  onPay,
326	  onCancel,
327	}: {
328	  invoice: Invoice;
329	  onOpen: () => void;
330	  onSend: () => void;
331	  onPay: () => void;
332	  onCancel: () => void;
333	}) {
334	  return (
335	    <>
336	      <button data-testid={`invoice-open-${invoice.id}`} onClick={onOpen}>
337	        Open
338	      </button>
339	      {invoice.status === 'DRAFT' && (
340	        <button data-testid={`invoice-send-${invoice.id}`} onClick={onSend}>
341	          Send
342	        </button>
343	      )}
344	      {invoice.status === 'SENT' && (
345	        <button data-testid={`invoice-pay-${invoice.id}`} onClick={onPay}>
346	          Mark paid
347	        </button>
348	      )}
349	      {invoice.status === 'SENT' && (
350	        <button data-testid={`invoice-cancel-${invoice.id}`} onClick={onCancel}>
351	          Cancel
352	        </button>
353	      )}
354	    </>
355	  );
356	}
