358	// The invoices raised against a project: what they add up to, a form to raise another, and a drill-in
359	// to each invoice's line items and payments. Owns its own invoice state, scoped to the one project.
360	// Whenever the invoices change (a new one raised, a status moved, a line item edited) the owner is
361	// told so figures derived from them — the budget's invoiced/remaining — can be refreshed.
362	function ProjectInvoices({
363	  projectId,
364	  onInvoicesChanged,
365	}: {
366	  projectId: number;
367	  onInvoicesChanged: () => void;
368	}) {
369	  const [invoices, setInvoices] = useState<Invoice[]>([]);
370	  const [amount, setAmount] = useState('');
371	  const [amountError, setAmountError] = useState('');
372	  const [sortByDue, setSortByDue] = useState(false);
373	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
374	
375	  async function load() {
376	    const res = await fetch(`/api/invoices?projectId=${projectId}`);
377	    setInvoices(await res.json());
378	    onInvoicesChanged();
379	  }
380	
381	  useEffect(() => {
382	    void load();
383	  }, [projectId]);
384	
385	  async function submit(e: React.FormEvent) {
386	    e.preventDefault();
387	    const value = Number(amount);
388	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
389	      setAmountError('Amount must be more than zero');
390	      return;
391	    }
392	    setAmountError('');
393	    await fetch('/api/invoices', {
394	      method: 'POST',
395	      headers: { 'Content-Type': 'application/json' },
396	      body: JSON.stringify({ projectId, amount: value }),
397	    });
398	    setAmount('');
399	    await load();
400	  }
401	
402	  // A lifecycle move (send, mark paid, …) is a POST to the matching action route followed by a reload;
403	  // routing them through one place means a new action is one more call site, not new plumbing.
404	  async function transition(id: number, action: 'send' | 'pay' | 'cancel') {
405	    await fetch(`/api/invoices/${id}/${action}`, { method: 'POST' });
406	    await load();
407	  }
408	
409	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
410	  const shownInvoices = sortByDue
411	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
412	    : invoices;
413	
414	  return (
415	    <>
416	      <form data-testid="invoice-form" onSubmit={submit}>
417	        <input
418	          data-testid="invoice-form-amount"
419	          placeholder="Amount"
420	          value={amount}
421	          onChange={(e) => setAmount(e.target.value)}
422	        />
423	        <button data-testid="invoice-form-submit" type="submit">
424	          Add invoice
425	        </button>
426	        {amountError && (
427	          <p data-testid="invoice-form-amount-error" role="alert">
428	            {amountError}
429	          </p>
430	        )}
431	      </form>
432	
433	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
434	        Sort by due date
435	      </button>
436	
437	      {openInvoiceId === null ? (
438	        <>
439	          <table data-testid="project-invoices-table">
440	            <tbody>
441	              {shownInvoices.map((inv) => (
442	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
443	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
444	                  <td data-testid="invoice-due-amount">{money(inv.amountDue)}</td>
445	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
446	                  <td data-testid="invoice-due">{inv.dueDate}</td>
447	                  <td data-testid="invoice-status">{inv.status}</td>
448	                  <td>
449	                    <InvoiceActions
450	                      invoice={inv}
451	                      onOpen={() => setOpenInvoiceId(inv.id)}
452	                      onSend={() => transition(inv.id, 'send')}
453	                      onPay={() => transition(inv.id, 'pay')}
454	                      onCancel={() => transition(inv.id, 'cancel')}
455	                    />
456	                  </td>
457	                </tr>
458	              ))}
459	            </tbody>
460	          </table>
461	
462	          <p data-testid="project-invoices-total">{money(total)}</p>
463	        </>
464	      ) : (
465	        <InvoiceDetail
466	          invoiceId={openInvoiceId}
467	          onChange={load}
468	          onClose={() => setOpenInvoiceId(null)}
469	        />
470	      )}
471	    </>
472	  );
473	}
